import { readFileSync } from 'node:fs'
import { addNote } from '@api/notes'

export async function main(input: { list: string }): Promise<number[]> {
  const ids: number[] = []
  for (const line of readFileSync(input.list, 'utf8').split('\n').filter(Boolean)) {
    const [text, tags = ''] = line.split('#')
    const note = await addNote(text.trim(), tags.split(',').map(tag => tag.trim()).filter(Boolean))
    ids.push(note.id)
  }
  return ids
}

import { byTag } from '@api/notes'

export async function main(): Promise<void> {
  await byTag(42)
}

import { writeFileSync } from 'node:fs'
import { byTag } from '@api/notes'

export async function main(): Promise<string[]> {
  const texts = (await byTag('shop')).map(note => note.text)
  writeFileSync('/tau/out/report.txt', texts.join('\n') + '\n')
  return texts
}
